html:
{%- 
    set is_rescheduled = doc.is_rescheduled == 1 or doc.entrance_test_status == "Rescheduled"
-%}

{%- if is_rescheduled -%}
    {%- set f_date = doc.re_allocation_date -%}
    {%- set f_test = doc.re_entrance_test_name or doc.re_entrance_test_list -%}
    {%- set f_seat = doc.re_seat_number -%}
    {%- set f_room = doc.re_room_name -%}
    {%- set f_code = doc.re_room_code -%}
    {%- set f_building = doc.re_building -%}
    {%- set f_floor = doc.re_floor -%}
    {%- set f_center = doc.re_center_name -%}
    {%- set f_address = doc.re_center_address -%}
    {%- set f_status = doc.re_allocation_status -%}
{%- else -%}
    {%- set f_date = doc.allocation_date -%}
    {%- set f_test = doc.entrance_test_name or doc.entrance_test_list -%}
    {%- set f_seat = doc.seat_number -%}
    {%- set f_room = doc.room_name -%}
    {%- set f_code = doc.room_code -%}
    {%- set f_building = doc.building -%}
    {%- set f_floor = doc.floor -%}
    {%- set f_center = doc.center_name -%}
    {%- set f_address = doc.center_address -%}
    {%- set f_status = doc.allocation_status -%}
{%- endif -%}

{%- set campus_display_name = frappe.db.get_value("Campus", doc.campus, "campus_name") if doc.campus else (doc.campus or "Institution of Legal Education") -%}
{%- set campus_logo_path = frappe.db.get_value("Campus", doc.campus, "logo") if doc.campus else None -%}
{%- set admit_no = doc.admit_card_number or ("AC-" + doc.name) -%}
{%- set dob = frappe.utils.formatdate(doc.date_of_birth) if doc.date_of_birth else "—" -%}
{%- set exam_date_time = (frappe.utils.formatdate(f_date) if f_date else "—") + " &nbsp;&middot;&nbsp; As per center schedule" -%}
{%- set centre_full = "<strong>" + (f_center or "—") + "</strong><br><span style='font-size:8.5px; color:#444;'>" + (f_address or "—") + "</span>" -%}

{%- set _site = frappe.utils.get_url() -%}

{#- Logo Handling -#}
{%- set _logo_src = '' -%}
{%- if campus_logo_path -%}
    {%- set _lb64 = get_file_b64(campus_logo_path) -%}
    {%- if _lb64 -%}
        {%- set _lext = (campus_logo_path.split('.')[-1] | lower) -%}
        {%- set _lmime = 'image/jpeg' if _lext in ['jpg','jpeg'] else ('image/png' if _lext == 'png' else 'image/svg+xml') -%}
        {%- set _logo_src = 'data:' ~ _lmime ~ ';base64,' ~ _lb64 -%}
    {%- else -%}
        {%- set _logo_src = _site ~ campus_logo_path -%}
    {%- endif -%}
{%- endif -%}

{#- Photo Handling -#}
{%- set _photo_src = '' -%}
{%- if doc.profile -%}
    {%- set _pb64 = get_file_b64(doc.profile) -%}
    {%- if _pb64 -%}
        {%- set _pext = (doc.profile.split('.')[-1] | lower) -%}
        {%- set _pmime = 'image/jpeg' if _pext in ['jpg','jpeg'] else ('image/png' if _pext == 'png' else 'image/webp') -%}
        {%- set _photo_src = 'data:' ~ _pmime ~ ';base64,' ~ _pb64 -%}
    {%- else -%}
        {%- set _photo_src = _site ~ doc.profile -%}
    {%- endif -%}
{%- endif -%}

<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=794, initial-scale=1.0">
<title>Admit Card - {{ admit_no }}</title>
<style>
  @page {
    size: 210mm 297mm;
    margin: 8mm 6mm;
  }
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  /* Reset Frappe wrapper elements */
  html, body, #page-body, .print-format-gutter, .print-format, .page-break, 
  .letter-head, .letter-head-content, form[data-doctype], .layout-main, 
  .layout-main-section, .frappe-card {
    margin: 0 !important; padding: 0 !important; border: none !important;
    background: transparent !important; width: auto !important; max-width: none !important;
  }

  body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 8.5px;
    color: #000;
    background: #fff;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .pf-page {
    width: 100%;
    margin: 0;
    padding: 0;
    border: 2px solid #7b1a1a;
    background: #fff;
    display: block;
    overflow: hidden;
    page-break-after: always;
  }

  @media screen {
    body { background: #888; }
    .pf-page {
      width: 760px;
      max-width: 760px;
      margin: 20px auto !important;
      box-shadow: 0 6px 28px rgba(0, 0, 0, .45);
    }
  }

  /* Header */
  .hdr {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    background: #7b1a1a !important;
    border-bottom: 2px solid #5a0e0e;
  }
  .hdr-logo-td { width: 68px; padding: 9px 10px; text-align: center; vertical-align: middle; }
  .hdr-text-td { padding: 9px 8px; text-align: center; vertical-align: middle; }
  .logo-box {
    width: 50px; height: 50px; background: #fff !important; border-radius: 4px;
    display: inline-block; overflow: hidden;
  }
  .logo-box img { width: 44px; height: 44px; display: block; margin: 3px auto; object-fit: contain; }
  .hdr-inst { font-size: 11pt; font-weight: bold; text-transform: uppercase; color: #fff !important; }
  .hdr-sub { font-size: 6pt; letter-spacing: 1px; text-transform: uppercase; color: #ffcccc !important; margin-top: 2px; }

  /* Title Strip */
  .title-bar {
    width: 100%; text-align: center; padding: 8px 10px; background: #fff8f8 !important;
    border-bottom: 1px solid #7b1a1a;
  }
  .title-main { font-size: 10pt; font-weight: bold; color: #5a0000; }
  .title-sub { font-size: 7pt; color: #666; margin-top: 2px; }

  /* Form Table */
  .ft {
    width: 100%; border-collapse: collapse; table-layout: fixed; margin-bottom: -1px;
  }
  .ft td {
    border: 1px solid #7b1a1a; padding: 5px 8px; vertical-align: middle;
    font-size: 8.5px; line-height: 1.4; word-wrap: break-word;
  }
  .lbl { font-weight: bold; background-color: #f0f0f0 !important; color: #111 !important; }
  .val { background-color: #fff !important; }
  .photo-td { text-align: center; vertical-align: middle !important; padding: 8px !important; background: #fafafa !important; }
  .photo-td img { width: 100px; height: 125px; display: block; margin: 0 auto 5px; border: 1px solid #7b1a1a; object-fit: cover; }
  .photo-cap { font-size: 6pt; color: #777; text-align: center; }

  .seat-pill {
    display: inline-block; background: #1a237e !important; color: #fff !important;
    font-weight: bold; padding: 2px 8px; border-radius: 2px;
  }
  .status-pill {
    display: inline-block; border: 1px solid #4caf50; color: #1b5e20; background: #f0fdf0 !important;
    font-size: 7pt; font-weight: bold; padding: 1px 6px; border-radius: 10px;
  }

  /* Instructions */
  .inst-sec { padding: 10px 15px; background: #fff; }
  .inst-title { font-size: 9pt; font-weight: bold; color: #7b1a1a; text-align: center; margin-bottom: 8px; text-transform: uppercase; border-bottom: 1px solid #7b1a1a; padding-bottom: 4px; }
  .sec-title { font-size: 8pt; font-weight: bold; color: #000; margin: 6px 0 3px; }
  .il { list-style: none; margin: 0; padding: 0; }
  .il li { display: flex; gap: 5px; font-size: 7.5pt; color: #111; line-height: 1.5; margin-bottom: 2px; }
  .mk { font-weight: bold; min-width: 15px; }

  /* Signature Table */
  .sig-tbl { width: 100%; border-collapse: collapse; margin-top: 0; }
  .sig-tbl td { border: 1px solid #7b1a1a; padding: 5px 10px 25px; text-align: center; font-size: 7.5pt; width: 50%; vertical-align: bottom; }
  .sig-head { font-weight: bold; background: #ebebeb !important; padding: 4px !important; vertical-align: middle !important; }

  .footer {
    border-top: 1px solid #7b1a1a; text-align: center; font-size: 7px; color: #888;
    padding: 5px; background: #fff8f8 !important;
  }
</style>
</head>
<body>
<div class="pf-page">
  <table class="hdr" cellspacing="0" cellpadding="0">
    <tr>
      <td class="hdr-logo-td">
        <div class="logo-box">
          {% if _logo_src %}<img src="{{ _logo_src }}" alt="Logo">
          {% else %}<div style="line-height:50px; color:#7b1a1a; font-weight:bold; font-size:14px;">ILE</div>{% endif %}
        </div>
      </td>
      <td class="hdr-text-td">
        <div class="hdr-inst">{{ campus_display_name }}</div>
        <div class="hdr-sub">OFFICE OF ADMISSIONS &nbsp;&middot;&nbsp; EXAMINATION CELL</div>
      </td>
    </tr>
  </table>

  <div class="title-bar">
    <div class="title-main">Admit Card ({{ f_test or "—" }})</div>
    <div class="title-sub">Admission to {{ doc.program_level or "the Programme" }} &nbsp;|&nbsp; {{ doc.academic_year or "—" }} &nbsp;|&nbsp; {{ doc.admission_cycle or "—" }}</div>
  </div>

  <table class="ft">
    <colgroup>
      <col style="width:20%"><col style="width:5%"><col style="width:25%">
      <col style="width:20%"><col style="width:5%"><col style="width:25%">
    </colgroup>
    <tr>
      <td class="lbl">Admit test Card No</td><td>:</td><td class="val"><strong>{{ admit_no }}</strong></td>
      <td class="photo-td" colspan="3" rowspan="7">
        {% if _photo_src %}<img src="{{ _photo_src }}" alt="Photo">
        {% else %}<div style="width:100px; height:125px; background:#eee; border:1px dashed #ccc; margin:0 auto; line-height:125px; color:#aaa;">No Photo</div>{% endif %}
        <div class="photo-cap">Candidate's Photograph</div>
      </td>
    </tr>
    <tr><td class="lbl">Candidate's Name</td><td>:</td><td class="val">{{ doc.candidate_name or "—" }}</td></tr>
    <tr><td class="lbl">Date of Birth</td><td>:</td><td class="val">{{ dob }}</td></tr>
    <tr><td class="lbl">Gender</td><td>:</td><td class="val">{{ doc.gender or "—" }}</td></tr>
    <tr><td class="lbl">Application No</td><td>:</td><td class="val">{{ doc.applicant or "—" }}</td></tr>
    <tr><td class="lbl">Father's Name</td><td>:</td><td class="val">{{ doc.father_name or "—" }}</td></tr>
    <tr><td class="lbl">Mother's Name</td><td>:</td><td class="val">{{ doc.mother_name or "—" }}</td></tr>

    <tr>
      <td class="lbl">Programme</td><td>:</td><td class="val" colspan="4">{{ doc.program or "—" }}</td>
    </tr>
    <tr>
      <td class="lbl">Exam Date & Time</td><td>:</td><td class="val" colspan="4">{{ exam_date_time|safe }}</td>
    </tr>
    <tr>
      <td class="lbl">Seat Number</td><td>:</td><td class="val"><span class="seat-pill">{{ f_seat or "—" }}</span></td>
      <td class="lbl">Reporting Time</td><td>:</td><td class="val">30 mins before</td>
    </tr>
    <tr>
      <td class="lbl">Room / Hall</td><td>:</td><td class="val">{{ f_room or "—" }}{% if f_code %} ({{ f_code }}){% endif %}</td>
      <td class="lbl">Status</td><td>:</td><td class="val"><span class="status-pill">{{ f_status or "—" }}</span></td>
    </tr>
    <tr>
      <td class="lbl">Building / Floor</td><td>:</td><td class="val" colspan="4">{{ f_building or "—" }}{% if f_floor %} &middot; Floor: {{ f_floor }}{% endif %}</td>
    </tr>
    <tr>
      <td class="lbl">Test Centre</td><td>:</td><td class="val" colspan="4">{{ centre_full|safe }}</td>
    </tr>
  </table>

  <div style="padding: 6px 15px; font-style: italic; font-size: 7.5pt; text-align: center; background: #fff8f8; border-bottom: 1px solid #7b1a1a;">
    To be signed in the presence of the Invigilator in the Examination Hall
  </div>

  <table class="sig-tbl">
    <tr>
      <td class="sig-head">Candidate's Signature</td>
      <td class="sig-head">Invigilator's Signature</td>
    </tr>
    <tr>
      <td style="height: 45px;"></td>
      <td style="height: 45px;"></td>
    </tr>
  </table>

  <div class="inst-sec">
    <div class="inst-title">Instructions to Candidates</div>
    <div class="sec-title">1. General Instructions</div>
    <ul class="il">
      <li><span class="mk">a.</span><span>Check details carefully. Report discrepancies to Examination Cell immediately.</span></li>
      <li><span class="mk">b.</span><span>Carry a printed copy of this admit card and a Govt. issued photo ID.</span></li>
    </ul>
    <div class="sec-title">2. Reporting & Timings</div>
    <ul class="il">
      <li><span class="mk">a.</span><span>Report 30 mins before start. Be seated 15 mins prior.</span></li>
      <li><span class="mk">b.</span><span>Entry cut-off time is strict. Latecomers will not be permitted.</span></li>
      <li><span class="mk">c.</span><span>No candidate allowed to leave until test ends and OMRs are collected.</span></li>
    </ul>
    <div class="sec-title">3. Permitted Items</div>
    <ul class="il">
      <li><span class="mk">a.</span><span>Admit Card, Photo ID, Black/Blue Ballpoint pen, Transparent water bottle, Face mask, Analogue watch.</span></li>
      <li><span class="mk">b.</span><span>Smart watches, mobile phones, and electronic devices are strictly prohibited.</span></li>
    </ul>
  </div>

  <div class="footer">
    Doc: <strong>{{ doc.name }}</strong> &nbsp;·&nbsp; Generated: {{ frappe.utils.formatdate(frappe.utils.nowdate()) }} &nbsp;·&nbsp; System-generated.
  </div>
</div>
</body>
</html>
